  function saveContact(){
    const phone=val('contact-phone').replace(/[\s()\-]/g,'');if(!val('contact-name')||!/^\+[1-9]\d{7,14}$/.test(phone))return fail('Add a name and valid international phone number.','contact-phone');
    if(val('contact-email')&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val('contact-email')))return fail('Enter a valid email or leave it empty.','contact-email');
    const duplicate=M.contacts.some((c,i)=>(!S.editContact||i!==S.contact)&&c.phone.replace(/[\s()\-]/g,'')===phone);if(duplicate)return fail('This phone already belongs to a contact. Review the existing record first.','contact-phone');const existing=S.editContact?M.contacts[S.contact]:null;const changed=existing&&existing.phone.replace(/[\s()\-]/g,'')!==phone;const contact={...(existing||{}),name:val('contact-name'),phone,email:val('contact-email'),country:val('contact-country'),zone:val('contact-zone'),timeBasis:val('contact-zone')==='Not confirmed'?'unknown':'reviewed-contact',initials:val('contact-name').split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase(),color:existing?.color||'sage'};if(!existing||changed){contact.status='Permission needed';contact.tone='amber';contact.source='No permission recorded for this number';contact.date='Not recorded';}if(S.editContact)M.contacts[S.contact]=contact;else{M.contacts.push(contact);S.contact=M.contacts.length-1;}S.state='default';close();render();toast('Contact saved in this preview. Calling permission was not granted.');
  }
  function download(){
    const selected=name=>Boolean(document.querySelector(`[name="export-${name}"]:checked`));
    if(!['outcomes','answers','nextsteps','phone','transcript'].some(selected))return fail('Choose at least one field group to export.');
    const audience=S.screen==='campaign'?(val('export-scope')==='filtered'?window.CampaignUX.filteredRecipients():window.CampaignUX.recipients()):[],questions=window.CampaignUX.questionDefinitions();
    const headers=['Name'];if(selected('outcomes'))headers.push('Outcome');if(selected('answers'))questions.forEach(q=>headers.push(q.text,q.text+' · status'));if(selected('nextsteps'))headers.push('Next step');if(selected('phone'))headers.push('Phone');if(selected('transcript')&&cap('transcript'))headers.push('Transcript excerpt');
    const rows=[headers,...audience.map(c=>{const r=[c.name];if(selected('outcomes'))r.push(c.outcome);if(selected('answers'))questions.forEach((q,i)=>r.push(c.answers[i]?.value||'',c.answers[i]?.status||'Unknown'));if(selected('nextsteps'))r.push(c.call===0?'Confirm a weekday morning':'');if(selected('phone'))r.push(c.phone);if(selected('transcript')&&cap('transcript'))r.push(c.call===0?'The team did a great job.':'');return r;})];
    const safe=x=>{const value=String(x);return /^[=+@\-\t\r]/.test(value)?"'"+value:value;};
    const csv=rows.map(r=>r.map(x=>'"'+safe(x).replace(/"/g,'""')+'"').join(',')).join('\r\n');
    const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='clinket-example-call-results.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);close();toast('Synthetic CSV downloaded for this view.');
  }
